$call = static fn(PDO $db, string $sql, array $params = []): array => GreenPortalDatabase::call($db, $sql, $params); $json = static fn(mixed $value): string => json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); $e = static fn(mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$types = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,100,0)', ['tabela' => 'vw_responsabilidade_tipos', 'filtros' => $json(['MODULO_CODIGO' => 'REQUISITOS_LEGAIS', 'ATIVO' => 1])]);
