$friendlyError = static function (Throwable $exception) use ($R): string { $raw = $exception->getMessage(); if (str_contains($raw, 'A data final nao pode ser anterior')) return $R('erro.data_final', 'A data final não pode ser anterior à data inicial.', 'The end date cannot be earlier than the start date.', 'La fecha final no puede ser anterior a la fecha inicial.'); if (str_contains($raw, 'Ja existe vinculo ativo')) return $R('erro.sobreposto', 'Já existe um responsável com este vínculo em um período sobreposto.', 'A responsible person with this link already exists in an overlapping period.', 'Ya existe un responsable con este vínculo en un período superpuesto.'); if (str_contains($raw, 'Grupo inexistente') || str_contains($raw, 'Usuario inexistente')) return $R('erro.inativo', 'O usuário ou grupo selecionado não está ativo.', 'The selected user or group is not active.', 'El usuario o grupo seleccionado no está activo.'); return $R('erro.salvar', 'Não foi possível salvar as responsabilidades. Verifique os dados informados.', 'Could not save the responsibilities. Check the data entered.', 'No fue posible guardar las responsabilidades. Verifique los datos informados.'); };
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'save_rows') {
    if (!$permission['pode_editar'] && !$permission['pode_incluir'] && !$permission['pode_excluir']) { http_response_code(403); exit($R('erro.sem_permissao_alterar', 'Sem permissão para alterar responsabilidades.', 'Not allowed to change responsibilities.', 'Sin permiso para modificar responsabilidades.')); }
    try {
        $existing = $call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_requisitos', 'filtros' => $json(['CODSITUACAO' => $id, 'ATIVO' => 1])]); $allowedIds = array_map('intval', array_column($existing, 'CODATRIBUICAO')); $postedKeys = array_map('strval', array_keys((array)($_POST['rows'] ?? [])));
        if ($permission['pode_excluir']) foreach ($existing as $old) {
