            if (!in_array($typeId, $validTypes, true) || !in_array($destination, ['USUARIO', 'GRUPO'], true) || ($destination === 'USUARIO' && !$userId) || ($destination === 'GRUPO' && !$groupId)) throw new RuntimeException($R('erro.preencha', 'Preencha finalidade e responsável em todas as linhas.', 'Fill in purpose and owner on every row.', 'Complete finalidad y responsable en todas las líneas.'));
