<select class="form-select form-select-sm js-group d-none" name="rows[<?= $key ?>][CODGRUPO]"><option value=""><?= $e($R('selecione', 'Selecione', 'Select', 'Seleccione')) ?></option><?php foreach ($groups as $group): ?><option value="<?= $e($group['CODGRUPO']) ?>"<?= (int)$group['CODGRUPO'] === (int)$row['CODGRUPO'] ? ' selected' : '' ?>><?= $e($group['NOME']) ?></option><?php endforeach; ?></select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows[<?= $key ?>][PRIORIDADE]" value="<?= $e($row['PRIORIDADE']) ?>"></td><td class="text-center"><input type="checkbox" name="rows[<?= $key ?>][PRINCIPAL]" value="1"<?= !empty($row['PRINCIPAL']) ? ' checked' : '' ?>></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_DE]" value="<?= $e($row['VALIDO_DE']) ?>"><input class="form-control form-control-sm" type="date" name="rows[<?= $key ?>][VALIDO_ATE]" value="<?= $e($row['VALIDO_ATE']) ?>"></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row" title="<?= $e($R('remover', 'Remover', 'Remove', 'Quitar')) ?>" data-testid="delete-responsibility-row"><i class="bi bi-trash"></i></button></td></tr><?php endforeach; ?></tbody></table></div><div class="d-flex justify-content-between mt-3"><button type="button" class="btn btn-sm btn-outline-primary" id="addRequisitoResponsibility" data-testid="add-responsibility-row"><i class="bi bi-plus-lg me-1"></i><?= $e($R('adicionar', 'Adicionar', 'Add', 'Agregar')) ?></button><button type="submit" class="btn btn-sm btn-success" id="saveRequisitoResponsibilities" data-testid="save-responsibilities"><i class="bi bi-check2 me-1"></i><?= $e($R('salvar', 'Salvar', 'Save', 'Guardar')) ?></button></div></form><?php endif; ?></main><script>document.addEventListener('DOMContentLoaded',function(){var L=<?= json_encode(['sel' => $R('selecione', 'Selecione', 'Select', 'Seleccione'), 'usu' => $R('destino.usuario', 'Usuário', 'User', 'Usuario'), 'gru' => $R('destino.grupo', 'Grupo', 'Group', 'Grupo'), 'rem' => $R('remover', 'Remover', 'Remove', 'Quitar')], JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT) ?>,table=document.querySelector('#requisitoResponsibilityTable tbody'),types=<?= json_encode($types, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,users=<?= json_encode($users, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,groups=<?= json_encode($groups, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,seq=0;function options(items,id){return '<option value="">'+L.sel+'</option>'+items.map(function(x){return '<option value="'+x[id]+'">'+String(x.NOME||'').replace(/</g,'&lt;')+'</option>';}).join('');}function toggle(row){var group=row.querySelector('.js-destination').value==='GRUPO';row.querySelector('.js-user').classList.toggle('d-none',group);row.querySelector('.js-group').classList.toggle('d-none',!group);}function bind(row){toggle(row);row.querySelector('.js-destination').addEventListener('change',function(){toggle(row);});}document.querySelectorAll('#requisitoResponsibilityTable tr[data-row-key]').forEach(bind);document.querySelector('#addRequisitoResponsibility')?.addEventListener('click',function(){var key='novo_'+(++seq),row=document.createElement('tr');row.innerHTML='<td><select class="form-select form-select-sm" name="rows['+key+'][CODTIPORESPONSABILIDADE]">'+types.map(function(x){return '<option value="'+x.CODTIPORESPONSABILIDADE+'">'+x.NOME+'</option>';}).join('')+'</select></td><td><select class="form-select form-select-sm js-destination" name="rows['+key+'][TIPO_DESTINO]"><option value="USUARIO">'+L.usu+'</option><option value="GRUPO">'+L.gru+'</option></select></td><td><select class="form-select form-select-sm js-user" name="rows['+key+'][CODUSUARIO]">'+options(users,'CODUSUARIO')+'</select><select class="form-select form-select-sm js-group d-none" name="rows['+key+'][CODGRUPO]">'+options(groups,'CODGRUPO')+'</select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows['+key+'][PRIORIDADE]" value="0"></td><td class="text-center"><input type="checkbox" name="rows['+key+'][PRINCIPAL]" value="1"></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_DE]" value="<?= date('Y-m-d') ?>"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_ATE]" value=""></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row" data-testid="delete-responsibility-row"><i class="bi bi-trash"></i></button></td>';table.appendChild(row);bind(row);});document.addEventListener('click',function(event){var button=event.target.closest('.js-delete-row');if(!button)return;var row=button.closest('tr'),key=row.getAttribute('data-row-key');if(key){var hidden=document.createElement('input');hidden.type='hidden';hidden.name='rows['+key+'][_delete]';hidden.value='1';row.appendChild(hidden);}row.remove();});});</script></body></html>
